import pytest
from ta_attenuator.attenuators_pool import AttenuatorsPool


def test_getting_attenuator_when_registry_is_empty_causes_exception():
    from ta_attenuator.attenuators_pool import AttenuatorsRegistryEmpty
    test_pool = AttenuatorsPool()
    with pytest.raises(AttenuatorsRegistryEmpty):
        test_pool.get_attenuator('JFW_168')
